fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    if n == 0 {
        return Vec::new();
    }

    // For n > 0, the resulting length is 2*n - 1.
    let mut res = Vec::with_capacity(2 * n - 1);

    // Push the first element without a leading delimiter.
    res.push(numbers[0]);

    // For each subsequent element, first push the delimiter, then the element.
    for &num in &numbers[1..] {
        res.push(delim);
        res.push(num);
    }

    res
}